import 'dart:io';
import 'classUser.dart';
import 'user_service.dart';
import 'user_service_config.dart';

void main() async {
  // Intentar cargar configuración desde archivo JSON (opcional). Ruta típica: config/user_service_config.json
  configService? config;
  final configPath = 'config/user_service_config.json';

  if (await File(configPath).exists()) {
    try {
      config = await configService.fromFile(configPath);
      print('Cargada configuración desde $configPath');
    } catch (e) {
      print('Error cargando configuración: $e');
    }
  }

  final service = UserService(config: config);
  // Lista de usuarios obtenidos de la API REST
  try {
    List<User> users = await service.fetchUsers();
    for (var user in users) {
      print(user);
    }

    // Ejemplo: recuperar un usuario por su ID
    try {
      final single = await service.fetchUserById(2);
      print('\nUsuario con id=2:');
      print(single);
    } catch (e) {
      print('Error al obtener usuario por id: $e');
    }
  } catch (e) {
    print(e);
  }
}
